import{_ as o,o as t,c as a,a3 as i}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"Hook Mechanism (inject runtime implementation)","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Hook Mechanism (inject runtime implementation) | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/catter/design/hook-mechanism"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/catter/design/hook-mechanism"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/design/hook-mechanism"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/design/hook-mechanism"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/design/hook-mechanism"}]]},"headers":[],"relativePath":"catter/design/hook-mechanism.md","filePath":"en/catter/design/hook-mechanism.md","lastUpdated":1792989239000}'),n={name:"catter/design/hook-mechanism.md"};function r(s,e,c,d,l,h){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="hook-mechanism-inject-runtime-implementation" tabindex="-1">Hook Mechanism (inject runtime implementation) <a class="header-anchor" href="#hook-mechanism-inject-runtime-implementation" aria-label="Permalink to &quot;Hook Mechanism (inject runtime implementation)&quot;">​</a></h1><blockquote><p>This page describes the internals of the <strong>inject runtime</strong>. Handler authors usually do not need to read it; it answers the platform-level question &quot;how are commands captured&quot;. For the capabilities and limitations handlers care about, see <a href="./runtime">Runtime</a>.</p></blockquote><p>The hook is the capture carrier of the inject runtime: a shared library loaded into every process spawned by the build system. Its sole job is to intercept process creation calls and rewrite them so that every child process goes through <code>catter-proxy</code> instead of executing directly.</p><p>The hook implementation is entirely platform-specific. Unix and Windows use fundamentally different interception techniques.</p><h2 id="unix-linux-and-macos-ld-preload-interception" tabindex="-1">Unix (Linux and macOS) -- LD_PRELOAD Interception <a class="header-anchor" href="#unix-linux-and-macos-ld-preload-interception" aria-label="Permalink to &quot;Unix (Linux and macOS) -- LD_PRELOAD Interception&quot;">​</a></h2><p>The Unix hook is a shared library loaded via the dynamic linker&#39;s preload mechanism:</p><ul><li><strong>Linux</strong>: <code>libcatter-hook-unix.so</code> loaded via <code>LD_PRELOAD</code></li><li><strong>macOS</strong>: <code>libcatter-hook-unix.dylib</code> loaded via <code>DYLD_INSERT_LIBRARIES</code></li></ul><h3 id="intercepted-functions" tabindex="-1">Intercepted Functions <a class="header-anchor" href="#intercepted-functions" aria-label="Permalink to &quot;Intercepted Functions&quot;">​</a></h3><p>The hook replaces all standard POSIX functions for creating new processes:</p><p><strong>exec family</strong>:</p><ul><li><code>execve()</code>, <code>execv()</code></li><li><code>execvpe()</code>, <code>execvp()</code>, <code>execvP()</code></li><li><code>execl()</code>, <code>execlp()</code>, <code>execle()</code></li></ul><p><strong>posix_spawn family</strong>:</p><ul><li><code>posix_spawn()</code></li><li><code>posix_spawnp()</code></li></ul><p>On Linux, the hook uses <code>dlsym(RTLD_NEXT, &quot;execve&quot;)</code> to obtain the original function pointer from the next library in the load order. It then provides a replacement function with the same signature. When the replacement is called, the hook can inspect and modify the arguments before optionally calling the original.</p><p>On macOS, the hook uses the <code>DYLD_INTERPOSE</code> macro to replace functions at the dyld level, which is the preferred technique on that platform.</p><p>dyld ends a program that cannot load a library inserted into it, and the hook is built for catter&#39;s own architecture, which Apple&#39;s own tools (arm64e) and Intel programs under Rosetta (x86_64) do not run as. Before it inserts the hook, <code>catter-proxy</code> asks dyld which architecture the program runs as (<code>macho_best_slice</code>; a script runs as its interpreter): a program of another runs without the hook, and what it starts is not captured. Where System Integrity Protection is on, dyld drops the hook from Apple&#39;s tools all the same, so a build is captured down to the Apple tools it runs and no further: <code>/usr/bin/make</code>, or <code>/bin/sh</code>, which Ninja runs every command with.</p><h3 id="key-classes" tabindex="-1">Key Classes <a class="header-anchor" href="#key-classes" aria-label="Permalink to &quot;Key Classes&quot;">​</a></h3><p>The hook is implemented as a set of cooperating classes:</p><ul><li><strong><code>Session</code></strong> -- Reads and stores session information from the environment (the proxy path, the self command ID and the session&#39;s pipe).</li><li><strong><code>find_program()</code></strong> (kotatsu) -- Finds the target executable as the exec function would, in <code>PATH</code> or the current directory; a program that is missing or cannot run fails as the call would.</li><li><strong><code>Command</code> / <code>build_proxy_command()</code></strong> -- Builds the rewritten proxy command, substituting <code>catter-proxy</code> for the original executable.</li><li><strong><code>SanitizedEnv</code> / <code>sanitize_environment()</code></strong> -- Scrubs the environment before the real <code>execve</code> is called. Removes catter variables and strips the hook library from the preload variable.</li><li><strong><code>Executor</code></strong> -- Orchestrates the interception. Validates the session, resolves the executable, builds the proxy command, cleans the environment, and calls the original function; it also holds the real <code>execve</code> / <code>posix_spawn</code> function pointers (the earlier standalone <code>Linker</code> class has been folded into it).</li></ul><h3 id="hook-initialization" tabindex="-1">Hook Initialization <a class="header-anchor" href="#hook-initialization" aria-label="Permalink to &quot;Hook Initialization&quot;">​</a></h3><p>The hook library is loaded via the dynamic linker&#39;s constructor mechanism (<code>on_load</code>, <code>__attribute__((constructor))</code>). During initialization, the library:</p><ol><li>Sets up logging (in debug builds, to <code>log/catter-hook.log</code> in the catter data directory)</li><li>Calls <code>Executor::init()</code>: reads session state from the environment and resolves the real <code>execve</code> / <code>posix_spawn</code> function pointers (<code>dlsym(RTLD_NEXT, ...)</code> on Linux, direct system symbols on macOS)</li></ol><h3 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h3><p>The hook reads session information from these environment variables, set by the proxy when it launches the build command:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>__key_catter_proxy_path_v1</code></td><td>Absolute path to the <code>catter-proxy</code> binary</td></tr><tr><td><code>__key_catter_command_id_v1</code></td><td>Session ID of the parent process</td></tr><tr><td><code>__key_catter_ipc_v1</code></td><td>The pipe of the catter session</td></tr></tbody></table><h3 id="interception-flow" tabindex="-1">Interception Flow <a class="header-anchor" href="#interception-flow" aria-label="Permalink to &quot;Interception Flow&quot;">​</a></h3><p>When any process creation function is called (e.g., <code>execve(&quot;/usr/bin/g++&quot;, argv, envp)</code>):</p><ol><li><p>The hook&#39;s replacement function is entered.</p></li><li><p><strong><code>Executor</code></strong> validates the session. If the session is invalid (missing environment variables), it builds an error command that reports the problem to the daemon.</p></li><li><p><strong><code>Executor</code></strong> finds the target executable with kotatsu&#39;s <code>find_program()</code>. For functions like <code>execvp()</code> and <code>execvpe()</code>, it searches the directories of <code>PATH</code>. For <code>execve()</code>, a path without a <code>/</code> is taken from the current directory.</p></li><li><p><strong><code>Command</code></strong> (<code>build_proxy_command()</code>) constructs the proxy command:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;proxy_path&gt; -p &lt;self_id&gt; --exec &lt;resolved_path&gt; --ipc &lt;pipe&gt; -- &lt;original_argv...&gt;</span></span></code></pre></div><p>The original <code>argv[0]</code> and all subsequent arguments are preserved after the <code>--</code> separator.</p></li><li><p><strong><code>SanitizedEnv</code></strong> (<code>sanitize_environment()</code>) modifies the environment array:</p><ul><li>Removes <code>__key_catter_proxy_path_v1</code>, <code>__key_catter_command_id_v1</code> and <code>__key_catter_ipc_v1</code></li><li>Strips the hook library name from <code>LD_PRELOAD</code> (or <code>DYLD_INSERT_LIBRARIES</code>)</li><li>If <code>LD_PRELOAD</code> becomes empty after stripping, removes it entirely</li></ul></li><li><p><strong><code>Executor</code></strong> calls the <strong>real</strong> <code>execve()</code> with the rewritten command (through the function pointers resolved during initialization).</p></li><li><p>If <code>execve</code> succeeds, it does not return (the current process image is replaced). If it fails, the hook restores <code>errno</code> and returns the error to the caller.</p></li></ol><h3 id="why-clean-the-environment" tabindex="-1">Why Clean the Environment? <a class="header-anchor" href="#why-clean-the-environment" aria-label="Permalink to &quot;Why Clean the Environment?&quot;">​</a></h3><p>This step is critical. If the hook library remained in <code>LD_PRELOAD</code> when <code>catter-proxy</code> is launched:</p><ol><li><code>catter-proxy</code> itself would be hooked</li><li>When the proxy tries to execute the actual compiler, the hook would intercept that call</li><li>The hook would rewrite it to launch another <code>catter-proxy</code></li><li>This creates <strong>infinite recursion</strong></li></ol><p>By stripping the hook from <code>LD_PRELOAD</code>, the proxy executes without interception. The proxy re-adds <code>LD_PRELOAD</code> only when it launches a command with the <code>INJECT</code> action, ensuring the hook is attached to the right processes.</p><h3 id="recursive-hooking" tabindex="-1">Recursive Hooking <a class="header-anchor" href="#recursive-hooking" aria-label="Permalink to &quot;Recursive Hooking&quot;">​</a></h3><p>Since <code>LD_PRELOAD</code> is inherited by child processes through the environment, interception is automatically recursive. Consider this build scenario:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span>
<span class="line"><span>  -&gt; sh -c &quot;gcc main.c -o main&quot;</span></span>
<span class="line"><span>     -&gt; gcc main.c -o main</span></span>
<span class="line"><span>        -&gt; cc1 main.c -o main.s</span></span>
<span class="line"><span>        -&gt; as main.s -o main.o</span></span>
<span class="line"><span>        -&gt; ld main.o -o main</span></span></code></pre></div><p>Every process in this tree inherits <code>LD_PRELOAD</code> and gets hooked. Each invocation goes through <code>catter-proxy</code>, which asks the daemon what to do. The build system is completely unaware of the interception.</p><hr><h2 id="windows-dll-injection-and-api-hooking" tabindex="-1">Windows -- DLL Injection and API Hooking <a class="header-anchor" href="#windows-dll-injection-and-api-hooking" aria-label="Permalink to &quot;Windows -- DLL Injection and API Hooking&quot;">​</a></h2><p>The Windows hook uses a fundamentally different approach because Windows has no equivalent to <code>LD_PRELOAD</code>. Instead, catter combines:</p><ol><li><strong>DLL injection</strong> -- to load the hook library into target processes</li><li><strong>API hooking via <a href="https://github.com/microsoft/Detours" target="_blank" rel="noreferrer">Microsoft Detours</a></strong> -- to intercept <code>CreateProcess</code> calls within those processes</li></ol><h3 id="hook-dlls" tabindex="-1">Hook DLLs <a class="header-anchor" href="#hook-dlls" aria-label="Permalink to &quot;Hook DLLs&quot;">​</a></h3><p>A process loads only DLLs of its own architecture, so there is one hook DLL per architecture, each installed next to <code>catter-proxy.exe</code>:</p><table tabindex="0"><thead><tr><th>DLL</th><th>Loaded into</th></tr></thead><tbody><tr><td><code>catter-hook-x64.dll</code></td><td>x64 processes, x64 processes emulated on ARM64, ARM64EC programs</td></tr><tr><td><code>catter-hook-arm64.dll</code></td><td>native ARM64 processes</td></tr></tbody></table><p>Every Windows build of catter carries both: on Windows on ARM, a build mixes native ARM64 tools with emulated x64 ones. A 32-bit (x86) process has no hook DLL yet: it runs without one, as it would without catter, and the commands it starts are not captured. catter-proxy logs a warning naming the program.</p><p>Each DLL is built without AddressSanitizer and with the C++ runtime linked in, importing only Windows&#39; own DLLs, UCRT among them: it runs inside every process of the build, which may lack other runtime DLLs, and Detours&#39; search of the address space reads ASan&#39;s shadow memory.</p><h3 id="environment-variables-1" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables-1" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>CATTER_IPC_ID</code></td><td>Session ID of the parent process</td></tr><tr><td><code>CATTER_IPC_PIPE</code></td><td>The pipe of the catter session</td></tr><tr><td><code>CATTER_PROXY_PATH</code></td><td>Absolute path to the <code>catter-proxy.exe</code> binary</td></tr></tbody></table><h3 id="dll-injection-process" tabindex="-1">DLL Injection Process <a class="header-anchor" href="#dll-injection-process" aria-label="Permalink to &quot;DLL Injection Process&quot;">​</a></h3><p>When <code>catter-proxy</code> (in injector mode) needs to start a build command with the hook attached:</p><ol><li><p><strong>Create the target process suspended</strong>. The proxy starts it with kotatsu&#39;s <code>kota::sys::spawn</code>, whose <code>windows_before_start</code> callback receives the process created, in a job object of its own, before its main thread runs.</p></li><li><p><strong>Set environment variables</strong>. <code>CATTER_IPC_ID</code>, <code>CATTER_IPC_PIPE</code> and <code>CATTER_PROXY_PATH</code> are set in the target process environment before creation (passed via the environment block).</p></li><li><p><strong>Find the process&#39;s architecture</strong>. <code>GetProcessInformation(ProcessMachineTypeInfo)</code> gives the machine whose code the process runs: x64 for x64 processes emulated on ARM64 and for ARM64EC ones, which <code>IsWow64Process2</code> cannot tell from native ARM64 processes. On Windows 10, which has no <code>ProcessMachineTypeInfo</code> and emulates no x64, <code>IsWow64Process2</code> gives it.</p></li><li><p><strong>Add the hook DLL to the process&#39;s imports</strong>. <code>DetourUpdateProcessWithDll()</code> adds the DLL of that architecture to the import table of the suspended executable, so the loader maps it before any of the program&#39;s own code runs. The loader reads the DLL&#39;s path there in the process&#39;s own ANSI code page, which a program can make UTF-8, so the path must be ASCII: a path that is not goes by its 8.3 short name, or, on a volume that keeps no short names, by a copy of the DLL in catter&#39;s data directory.</p></li><li><p><strong>Resume the main thread</strong>. Once the callback returns, <code>spawn</code> resumes the main thread. The loader maps the hook DLL with the program&#39;s other imports, and its hooks are active before the program&#39;s entry point runs.</p></li></ol><h3 id="hooked-windows-apis" tabindex="-1">Hooked Windows APIs <a class="header-anchor" href="#hooked-windows-apis" aria-label="Permalink to &quot;Hooked Windows APIs&quot;">​</a></h3><p>The hook DLL attaches Detours hooks to these functions in one transaction during <code>DLL_PROCESS_ATTACH</code>:</p><ul><li><strong><code>CreateProcessA()</code></strong> -- ANSI version of process creation</li><li><strong><code>CreateProcessW()</code></strong> -- Wide-character version of process creation</li></ul><p>A process a program starts under another account&#39;s token (<code>CreateProcessAsUser</code>, <code>CreateProcessWithTokenW</code>, <code>CreateProcessWithLogonW</code>) runs without the hook and is not captured: <code>catter-proxy</code> would have to run under that token too, and that account may be unable to start it or to reach the session&#39;s pipe.</p><p>Detours works by:</p><ol><li>Saving the first few instructions of the target function</li><li>Overwriting them with a jump to the detour function</li><li>Providing a trampoline that contains the saved instructions followed by a jump back, so the original function can still be called</li></ol><h3 id="hook-detour-logic" tabindex="-1">Hook Detour Logic <a class="header-anchor" href="#hook-detour-logic" aria-label="Permalink to &quot;Hook Detour Logic&quot;">​</a></h3><p>When <code>CreateProcessA</code> or <code>CreateProcessW</code> is called by the hooked process:</p><ol><li><p><strong>Extract the command line</strong>. The hook reads <code>lpApplicationName</code> and <code>lpCommandLine</code>.</p></li><li><p><strong>Resolve the program</strong>. The hook resolves it with <code>resolve_program()</code>: <code>lpApplicationName</code> made absolute from the current directory, or else the first token of the command line, looked for as <code>CreateProcess</code> looks for it (kotatsu&#39;s <code>find_create_process_program</code>: the program&#39;s directory, the current directory, the system directories, the Windows directory, then <code>PATH</code>).</p></li><li><p><strong>Rewrite the command line</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{proxy_path} -p {ipc_id} --exec {resolved_path} --ipc {pipe} -- {original_cmdline}</span></span></code></pre></div><p>The <code>lpApplicationName</code> is set to <code>nullptr</code> so that the command line is parsed by <code>CreateProcess</code> normally.</p></li><li><p><strong>Call the original <code>CreateProcess</code></strong> via the Detours trampoline with the modified command line.</p></li></ol><h3 id="key-difference-from-unix" tabindex="-1">Key Difference from Unix <a class="header-anchor" href="#key-difference-from-unix" aria-label="Permalink to &quot;Key Difference from Unix&quot;">​</a></h3><p>On Unix, <code>LD_PRELOAD</code> is an environment variable inherited automatically by all child processes. The hook is &quot;viral&quot; by default -- every subprocess gets it.</p><p>On Windows, there is no such mechanism. The hook DLL must be explicitly injected into each new process. This happens because:</p><ol><li>The hook&#39;s <code>CreateProcess</code> detour intercepts every process creation</li><li>It rewrites the command to go through <code>catter-proxy</code></li><li>When the proxy decides to execute with <code>INJECT</code> action, it performs DLL injection into the new process (create suspended, inject, resume)</li></ol><p>This means the proxy is responsible for re-injecting the hook into each generation of child processes, maintaining the recursive interception chain. Processes of different architectures can alternate along the chain: each gets the hook DLL of its own.</p><h3 id="dll-lifecycle" tabindex="-1">DLL Lifecycle <a class="header-anchor" href="#dll-lifecycle" aria-label="Permalink to &quot;DLL Lifecycle&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DLL_PROCESS_ATTACH:</span></span>
<span class="line"><span>  DetourRestoreAfterWith()   -- Restore the import table catter-proxy changed</span></span>
<span class="line"><span>  DetourTransactionBegin()</span></span>
<span class="line"><span>  DetourAttach(...)          -- Hook CreateProcessA and CreateProcessW</span></span>
<span class="line"><span>  DetourTransactionCommit()  -- Activate all hooks at once</span></span></code></pre></div><p><code>DisableThreadLibraryCalls()</code> is called during attach to suppress <code>DLL_THREAD_ATTACH</code> and <code>DLL_THREAD_DETACH</code> notifications, reducing overhead. The DLL is an import of the executable, unloaded only with the process, so <code>DLL_PROCESS_DETACH</code> has nothing to undo. It exports ordinal 1, as every DLL Detours injects must.</p><h2 id="platform-comparison" tabindex="-1">Platform Comparison <a class="header-anchor" href="#platform-comparison" aria-label="Permalink to &quot;Platform Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>Linux</th><th>macOS</th><th>Windows</th></tr></thead><tbody><tr><td>Hook library</td><td><code>libcatter-hook-unix.so</code></td><td><code>libcatter-hook-unix.dylib</code></td><td><code>catter-hook-{x64,arm64}.dll</code></td></tr><tr><td>Injection method</td><td><code>LD_PRELOAD</code> env var</td><td><code>DYLD_INSERT_LIBRARIES</code> env var</td><td><code>DetourUpdateProcessWithDll</code></td></tr><tr><td>Interposition</td><td><code>dlsym(RTLD_NEXT, ...)</code></td><td><code>DYLD_INTERPOSE</code> macro</td><td>Detours trampoline hooking</td></tr><tr><td>Intercepted APIs</td><td><code>execve</code>, <code>execvp</code>, <code>posix_spawn</code>, etc.</td><td>Same as Linux</td><td><code>CreateProcessA</code>, <code>CreateProcessW</code></td></tr><tr><td>Recursive hooking</td><td>Automatic (env inherited)</td><td>Automatic (env inherited)</td><td>Explicit (DLL re-injected per process)</td></tr><tr><td>Env vars for session</td><td><code>__key_catter_proxy_path_v1</code>, <code>__key_catter_command_id_v1</code></td><td>Same as Linux</td><td><code>CATTER_PROXY_PATH</code>, <code>CATTER_IPC_ID</code></td></tr></tbody></table>`,69)])])}const u=o(n,[["render",r]]);export{m as __pageData,u as default};
